define({"topics":[{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_Parent_26.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e122993","topics":[]},{"title":"Applying LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_35.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e123096","topics":[]},{"title":"Removing the rear pedestal covers","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RemovingRearPedestalCovers_13.html","attributes":{"data-id":"id_2008055"},"menu":{"hasChildren":false},"tocID":"id_2008055-d46e123198","topics":[]},{"title":"Replacing the sensor flag","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_ReplacingTheSensorFlag.html","attributes":{"data-id":"id_2011811"},"menu":{"hasChildren":false},"tocID":"id_2011811-d46e123299","topics":[]},{"title":"Installing the rear pedestal covers","shortdesc":"<p class=\"shortdesc\">Instruction for installing the rear pedestal covers.<\/p>","href":"t_InstallingTheRearPedestalCovers_12.html","attributes":{"data-id":"id_2007670"},"menu":{"hasChildren":false},"tocID":"id_2007670-d46e123400","topics":[]},{"title":"Removing LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_28.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e123502","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_27.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e123604","topics":[]},{"title":"Calibrating the longitudinal drive","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_CalibratingTheLongitudinalDrive.html","attributes":{"data-id":"id_2011734"},"menu":{"hasChildren":false},"tocID":"id_2011734-d46e123706","topics":[]},{"title":"Doing DQA calibration with the DQA III phantom","shortdesc":"<p class=\"shortdesc\">The DQA tool determines correct gradient polarity and correct gradient wiring by scanning a series of axial and coronal images of the DQA III phantom for systems below sentence MR 31.0 or sites that do not have a 17cm Sphere with Spout (SWS) phantom.<\/p>","href":"t_DoingDQACalibration_4.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e123808","topics":[]},{"title":"Doing DQA calibration <span class=\"ph\">with the Sphere With Spout (SWS) phantom<\/span>","shortdesc":"<p class=\"shortdesc\">Details the steps needed to run the Gradient Calibration Tool (GCT) for systems running MR31.0 and higher<span class=\"ph\"> and that possess the 17cm Sphere with Spout (SWS) phantom<\/span>. GCT does the same checks and produces the same output as DQA.<\/p>","href":"t_DoingDQACalibrationsforMR31andHigher_4.html","attributes":{"data-id":"id_2068424"},"menu":{"hasChildren":false},"tocID":"id_2068424-d46e123911","topics":[]}]});